// Posiciones contadas desde 1 (la raíz es la 1): los hijos de k son 2k y 2k+1, y el padre de k es floor(k/2)

// Camino desde la raíz hasta la posición k, subiendo de padre en padre
function caminoSubiendo(k) {
  const pasos = [];
  while (k > 1) { pasos.unshift(k % 2 === 0 ? "izquierda" : "derecha"); k = Math.floor(k / 2); }
  return pasos;
}

// Camino leyendo los bits de k, sin el primer 1 (0 = izquierda, 1 = derecha)
function caminoPorBits(k) {
  return k.toString(2).slice(1).split("").filter(b => b !== "").map(b => (b === "0" ? "izquierda" : "derecha"));
}

for (const k of [11, 6, 1000000]) {
  const bits = k.toString(2);
  const igual = caminoSubiendo(k).join() === caminoPorBits(k).join();
  console.log(`posición ${k} = ${bits} en binario (${bits.length} bits). Los dos caminos coinciden: ${igual}`);
}
console.log("Camino a la posición 11:", caminoSubiendo(11).join(", "));

