// Montículo de mínimos sobre un array: el hijo izquierdo de i está en 2i+1, el derecho en 2i+2
class Monticulo {
  constructor(antes = (x, y) => x < y) { this.a = []; this.antes = antes; this.comparaciones = 0; }
  menor(i, j) { this.comparaciones++; return this.antes(this.a[i], this.a[j]); }
  intercambiar(i, j) { [this.a[i], this.a[j]] = [this.a[j], this.a[i]]; }
  insertar(x) {
    this.a.push(x);                          // 1. al final: así se mantiene la forma
    let i = this.a.length - 1;
    while (i > 0) {                          // 2. subir mientras sea menor que su padre
      const padre = Math.floor((i - 1) / 2);
      if (!this.menor(i, padre)) break;
      this.intercambiar(i, padre);
      i = padre;
    }
  }
  extraer() {
    const a = this.a;
    const primero = a[0];
    const ultimo = a.pop();                  // 1. sacar el último elemento
    if (a.length > 0) {
      a[0] = ultimo;                         // 2. ponerlo en la raíz
      let i = 0;
      while (true) {                         // 3. bajar, cambiando siempre por el hijo menor
        let h = 2 * i + 1;
        if (h >= a.length) break;
        if (h + 1 < a.length && this.menor(h + 1, h)) h++;
        if (!this.menor(h, i)) break;
        this.intercambiar(i, h);
        i = h;
      }
    }
    return primero;
  }
}

