// Datos inventados: n urgencias al azar (generador con semilla fija: sale siempre lo mismo)
let semilla = 20261113;
const azar = () => (semilla = (semilla * 16807) % 2147483647) / 2147483647;

// Opción 1: lista sin ordenar. Para cada salida hay que recorrer todo lo que queda
function sacarTodoRecorriendo(lista) {
  const a = lista.slice(), salida = [];
  let comparaciones = 0;
  while (a.length > 0) {
    let k = 0;
    for (let i = 1; i < a.length; i++) { comparaciones++; if (a[i] < a[k]) k = i; }
    salida.push(a.splice(k, 1)[0]);
  }
  return { salida, comparaciones };
}

// Opción 2: montículo (la clase Monticulo de arriba, sin cambios)
function sacarTodoConMonticulo(lista) {
  const m = new Monticulo(), salida = [];
  for (const x of lista) m.insertar(x);
  while (m.a.length > 0) salida.push(m.extraer());
  return { salida, comparaciones: m.comparaciones };
}

for (const n of [1000, 10000]) {
  const urgencias = Array.from({ length: n }, () => Math.floor(azar() * 100000));
  const r1 = sacarTodoRecorriendo(urgencias);
  const r2 = sacarTodoConMonticulo(urgencias);
  const igual = r1.salida.every((x, i) => x === r2.salida[i]);
  console.log(`n = ${n}: recorriendo ${r1.comparaciones.toLocaleString("es-AR")} comparaciones, ` +
              `montículo ${r2.comparaciones.toLocaleString("es-AR")}, mismo orden de salida: ${igual}`);
}

use std::cmp::Reverse;
use std::collections::BinaryHeap;

fn main() {
    let mut cola = BinaryHeap::new();
    for limite in [240, 90, 480, 45] {
        cola.push(limite);
    }
    println!("BinaryHeap saca primero: {:?}", cola.pop()); // el MAYOR

    let mut urgentes = BinaryHeap::new();
    for limite in [240, 90, 480, 45] {
        urgentes.push(Reverse(limite));
    }
    println!("Con Reverse saca primero: {:?}", urgentes.pop()); // el menor
}

