// DATOS INVENTADOS: 200.000 importes de pedidos en pesos (generador con semilla fija)
let semilla = 7;
const azar = () => (semilla = (semilla * 16807) % 2147483647) / 2147483647;
const flujo = Array.from({ length: 200000 }, () => 1000 + Math.floor(azar() * 9999000));
const K = 5;

// Con montículo: guardamos solo los K importes más altos vistos hasta ahora.
// Es un montículo de MÍNIMOS: su raíz es el menor de los elegidos, el primero en salir.
const m = new Monticulo();
let entraron = 0, contraLaRaiz = 0;       // contraLaRaiz: comparar cada importe nuevo con el menor de los elegidos
for (const importe of flujo) {
  if (m.a.length < K) { m.insertar(importe); entraron++; continue; }
  contraLaRaiz++;
  if (importe > m.a[0]) { m.extraer(); m.insertar(importe); entraron++; }
}
const conMonticulo = m.a.slice().sort((x, y) => y - x);

// Ordenando todo (contamos cuántas comparaciones hace sort)
let comparacionesSort = 0;
const ordenada = flujo.slice().sort((x, y) => { comparacionesSort++; return y - x; });
const top = ordenada.slice(0, K);

console.log("Los 5 mayores con montículo:  ", conMonticulo.join(", "));
console.log("Los 5 mayores ordenando todo: ", top.join(", "));
console.log("Mismos resultados:", conMonticulo.join() === top.join());
console.log(`Montículo: ${(m.comparaciones + contraLaRaiz).toLocaleString("es-AR")} comparaciones; entraron ${entraron} de ${flujo.length} y guardó solo ${K}`);
console.log(`Ordenar todo: ${comparacionesSort.toLocaleString("es-AR")} comparaciones y guardó los ${flujo.length}`);

// Peor caso para el montículo: datos que llegan siempre en orden creciente (todos entran)
const peor = new Monticulo();
let contra2 = 0;
for (let x = 1; x <= 200000; x++) {
  if (peor.a.length < K) { peor.insertar(x); continue; }
  contra2++;
  if (x > peor.a[0]) { peor.extraer(); peor.insertar(x); }
}
console.log(`Si llegan en orden creciente: ${(peor.comparaciones + contra2).toLocaleString("es-AR")} comparaciones (entran todos)`);
